fn pop(v: &Vec<Int>) -> Vec<Int> {
    if v.len() == 0 {
        return vec()
    }
    let mut nv = vec()
    for i in 0 < v.len() - 1 {
        nv = push(nv, get(v, i))
    }
    nv
}

fn get(v: &Vec<Int>, i: Int) -> Int {
    if i >= v.len() {
        panic("Index out of bounds")
    }
    v.get(i)
}

fn push(v: Vec<Int>, x: Int) -> Vec<Int> {
    let mut nv = vec()
    for i in 0 < v.len() {
        nv = push(nv, get(&v, i))
    }
    nv.push(x)
}

